package com.dataconnect.hub.security;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Date;

@Component
public class JwtUtil {

    private final SecretKey key;
    private final long expiration;

    public JwtUtil(@Value("${jwt.secret}") String secret,
                   @Value("${jwt.expiration}") long expiration) {
        this.key = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
        this.expiration = expiration;
    }

    public String generateToken(String username, String role) {
        Date now = new Date();
        return Jwts.builder()
                .subject(username)
                .claim("role", role)
                .issuedAt(now)
                .expiration(new Date(now.getTime() + expiration))
                .signWith(key)
                .compact();
    }

    public String extractUsername(String token) {
        return parseClaims(token).getSubject();
    }

    public boolean validateToken(String token) {
        try {
            parseClaims(token);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private Claims parseClaims(String token) {
        return Jwts.parser()
                .verifyWith(key)
                .build()
                .parseSignedClaims(token)
                .getPayload();
    }
}

package com.dataconnect.hub.service;

import com.dataconnect.hub.dto.DatasourceConfigRequest;
import com.dataconnect.hub.dto.TestConnectionRequest;
import com.dataconnect.hub.entity.ConnectionLog;
import com.dataconnect.hub.entity.DatasourceConfig;
import com.dataconnect.hub.repository.ConnectionLogRepository;
import com.dataconnect.hub.repository.DatasourceConfigRepository;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Service
public class DatasourceConfigService {

    private final DatasourceConfigRepository configRepo;
    private final ConnectionLogRepository logRepo;
    private final DatasourceConnectionService connectionService;

    public DatasourceConfigService(DatasourceConfigRepository configRepo,
                                   ConnectionLogRepository logRepo,
                                   DatasourceConnectionService connectionService) {
        this.configRepo = configRepo;
        this.logRepo = logRepo;
        this.connectionService = connectionService;
    }

    public DatasourceConfig create(Long userId, DatasourceConfigRequest request) {
        DatasourceConfig config = new DatasourceConfig();
        config.setUserId(userId);
        config.setConfigName(request.getConfigName());
        config.setDbType(request.getDbType());
        config.setHost(request.getHost());
        config.setPort(request.getPort());
        config.setDatabaseName(request.getDatabaseName());
        config.setUsername(request.getUsername());
        config.setPassword(request.getPassword());
        config.setExtraParams(request.getExtraParams());
        config.setStatus("ACTIVE");
        config.setCreatedAt(LocalDateTime.now());
        return configRepo.save(config);
    }

    public List<DatasourceConfig> listByUser(Long userId) {
        return configRepo.findByUserIdOrderByCreatedAtDesc(userId);
    }

    public DatasourceConfig getByIdAndUser(Long id, Long userId) {
        return configRepo.findById(id)
                .filter(c -> c.getUserId().equals(userId))
                .orElse(null);
    }

    public DatasourceConfig update(Long id, Long userId, DatasourceConfigRequest request) {
        DatasourceConfig config = getByIdAndUser(id, userId);
        if (config == null) return null;

        config.setConfigName(request.getConfigName());
        config.setDbType(request.getDbType());
        config.setHost(request.getHost());
        config.setPort(request.getPort());
        config.setDatabaseName(request.getDatabaseName());
        config.setUsername(request.getUsername());
        config.setPassword(request.getPassword());
        config.setExtraParams(request.getExtraParams());
        config.setUpdatedAt(LocalDateTime.now());
        return configRepo.save(config);
    }

    public boolean delete(Long id, Long userId) {
        DatasourceConfig config = getByIdAndUser(id, userId);
        if (config == null) return false;
        configRepo.delete(config);
        return true;
    }

    public Map<String, Object> testConnection(Long id, Long userId, TestConnectionRequest override) {
        DatasourceConfig config = getByIdAndUser(id, userId);
        if (config == null) return null;

        String effectiveHost = (override.getHost() != null && !override.getHost().isEmpty())
                ? override.getHost() : config.getHost();
        String effectiveDatabaseName = (override.getDatabaseName() != null && !override.getDatabaseName().isEmpty())
                ? override.getDatabaseName() : config.getDatabaseName();
        String effectiveUsername = (override.getUsername() != null && !override.getUsername().isEmpty())
                ? override.getUsername() : config.getUsername();
        String effectivePassword = *** != null && !override.getPassword().isEmpty())
                ? override.getPassword() : config.getPassword();
        Integer effectivePort = override.getPort() != null ? override.getPort() : config.getPort();
        String effectiveExtraParams = override.getExtraParams() != null
                ? override.getExtraParams() : config.getExtraParams();

        ConnectionTestResult result = connectionService.testConnection(
                config.getDbType(), effectiveHost, effectivePort, effectiveDatabaseName,
                effectiveUsername, effectivePassword, effectiveExtraParams);

        ConnectionLog log = new ConnectionLog();
        log.setConfigId(id);
        log.setUserId(userId);
        log.setJdbcUrl(result.getJdbcUrl());
        log.setSuccess(result.isSuccess());
        log.setErrorMessage(result.getErrorMessage());
        log.setCreatedAt(LocalDateTime.now());
        logRepo.save(log);

        Map<String, Object> map = new LinkedHashMap<>();
        map.put("success", result.isSuccess());
        map.put("jdbcUrl", result.getJdbcUrl());
        if (result.isSuccess()) {
            map.put("responseTimeMs", result.getResponseTimeMs());
        } else {
            map.put("errorMessage", result.getErrorMessage());
        }
        return map;
    }

    public QueryResult executeQuery(Long id, Long userId, String sql) {
        DatasourceConfig config = getByIdAndUser(id, userId);
        if (config == null) return null;

        return connectionService.executeQuery(
                config.getDbType(), config.getHost(), config.getPort(),
                config.getDatabaseName(), config.getUsername(), config.getPassword(),
                config.getExtraParams(), sql);
    }

    public List<ConnectionLog> getLogs(Long id, Long userId) {
        if (getByIdAndUser(id, userId) == null) return null;
        return logRepo.findByConfigIdOrderByCreatedAtDesc(id);
    }
}

package com.dataconnect.hub.service;

import org.springframework.stereotype.Service;

import java.sql.*;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Service
public class DatasourceConnectionService {

    public ConnectionTestResult testConnection(String dbType, String host, int port,
                                               String databaseName, String username,
                                               String password, String extraParams) {
        String jdbcUrl = buildJdbcUrl(dbType, host, port, databaseName, extraParams);
        long start = System.currentTimeMillis();
        try {
            Connection conn = DriverManager.getConnection(jdbcUrl, username, password);
            conn.close();
            long elapsed = System.currentTimeMillis() - start;
            return new ConnectionTestResult(true, jdbcUrl, null, elapsed);
        } catch (SQLException e) {
            long elapsed = System.currentTimeMillis() - start;
            return new ConnectionTestResult(false, jdbcUrl, e.getMessage(), elapsed);
        }
    }

    public QueryResult executeQuery(String dbType, String host, int port,
                                    String databaseName, String username,
                                    String password, String extraParams, String sql) {
        String jdbcUrl = buildJdbcUrl(dbType, host, port, databaseName, extraParams);
        try (Connection conn = DriverManager.getConnection(jdbcUrl, username, password);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();
            List<String> columns = new ArrayList<>();
            for (int i = 1; i <= colCount; i++) {
                columns.add(meta.getColumnLabel(i));
            }

            List<Map<String, Object>> rows = new ArrayList<>();
            while (rs.next()) {
                Map<String, Object> row = new LinkedHashMap<>();
                for (int i = 0; i < colCount; i++) {
                    Object val = rs.getObject(i + 1);
                    row.put(columns.get(i), val != null ? val.toString() : null);
                }
                rows.add(row);
            }

            return new QueryResult(true, columns, rows, rows.size(), null);
        } catch (SQLException e) {
            return new QueryResult(false, null, null, 0, e.getMessage());
        }
    }

    private String buildJdbcUrl(String dbType, String host, int port,
                                String databaseName, String extraParams) {
        String scheme = "POSTGRESQL".equalsIgnoreCase(dbType)
                ? "jdbc:postgresql://" : "jdbc:mysql://";
        String base = scheme + host + ":" + port + "/" + databaseName;
        if (extraParams != null && !extraParams.isBlank()) {
            base += "?" + extraParams;
        }
        return base;
    }
}
